export function filterObservations(data,{year='2025',month='all',maxUncertainty=1000}={}){return data.records.filter(r=>(year==='all'||r.year===Number(year))&&(month==='all'||r.month===Number(month))&&(maxUncertainty===Infinity||r.uncertaintyMeters!=null&&r.uncertaintyMeters<=maxUncertainty));}
